function createDataClient({ fetchImpl, ttl }) {
  const cache = new Map();
  const inflight = new Map();
  return {
    async get(url) {
      const hit = cache.get(url);
      const now = Date.now();
      if (hit && now < hit.expiresAt) {
        console.log(`  [${url}] cache HIT`);
        return hit.data;
      }
      if (inflight.has(url)) {
        console.log(`  [${url}] deduped: joining in-flight request`);
        return inflight.get(url);
      }
      console.log(`  [${url}] fetching...`);
      const p = fetchImpl(url).then((data) => {
        cache.set(url, { data, expiresAt: Date.now() + ttl });
        inflight.delete(url);
        return data;
      });
      inflight.set(url, p);
      return p;
    },
    _cache: cache
  };
}

async function main() {
  let calls = 0;
  const fakeFetch = async (url) => {
    calls++;
    await new Promise((r) => setTimeout(r, 10));
    return { url: url, rows: calls };
  };
  const api = createDataClient({ fetchImpl: fakeFetch, ttl: 60000 });

  const ab = await Promise.all([api.get("/users"), api.get("/users")]);
  console.log("concurrent: same object?", ab[0] === ab[1], "| fetch calls:", calls);

  const c = await api.get("/users");
  console.log("sequential: cache hit?", c === ab[0], "| fetch calls:", calls);

  api._cache.get("/users").expiresAt = Date.now() - 1;
  const d = await api.get("/users");
  console.log("after expiry: refetched?", d !== ab[0], "| fetch calls:", calls);
}

main();

