const EMPLOYEES = [
  { id: 1, name: "Ava Chen", role: "engineer", level: "senior", location: "SF" },
  { id: 2, name: "Ben Ortiz", role: "designer", level: "mid", location: "NYC" },
  { id: 3, name: "Cara Wu", role: "engineer", level: "staff", location: "SF" },
  { id: 4, name: "Dan Kim", role: "engineer", level: "mid", location: "Remote" },
  { id: 5, name: "Eva Novak", role: "manager", level: "senior", location: "NYC" },
  { id: 6, name: "Finn Lee", role: "engineer", level: "junior", location: "SF" }
];

const LEVEL_RANK = { junior: 1, mid: 2, senior: 3, staff: 4 };

function applyFilters(rows, opts) {
  const query = opts.query || "";
  const role = opts.role || "all";
  const sortBy = opts.sortBy || "name";
  const sortDir = opts.sortDir || "asc";
  const q = query.trim().toLowerCase();
  const filtered = rows.filter((r) => {
    const roleOk = role === "all" || r.role === role;
    const qOk = q === "" || r.name.toLowerCase().indexOf(q) !== -1 || r.location.toLowerCase().indexOf(q) !== -1;
    return roleOk && qOk;
  });
  const dir = sortDir === "desc" ? -1 : 1;
  const val = (r) => (sortBy === "level" ? LEVEL_RANK[r.level] : r[sortBy]);
  return filtered.slice().sort((a, b) => {
    const av = val(a);
    const bv = val(b);
    return (av < bv ? -1 : av > bv ? 1 : 0) * dir;
  });
}

function ids(rows) { return rows.map((r) => r.id).join(","); }
console.log("q1 engineers, level desc:", ids(applyFilters(EMPLOYEES, { role: "engineer", sortBy: "level", sortDir: "desc" })));
console.log("q2 query \"nyc\":", ids(applyFilters(EMPLOYEES, { query: "nyc" })));
console.log("q3 query \"a\", name asc:", ids(applyFilters(EMPLOYEES, { query: "a", sortBy: "name" })));
console.log("input unmutated:", EMPLOYEES.map((r) => r.id).join(",") === "1,2,3,4,5,6");

