function DataTable(props) {
  const rows = props.rows;
  const columns = props.columns;
  const sortBy = props.sortBy;
  const sortDir = props.sortDir;
  const onSort = props.onSort;
  const loading = props.loading;
  const selectedId = props.selectedId;
  const onSelect = props.onSelect;

  if (loading) {
    return (
      <div role="status" aria-busy="true" aria-label="Loading results">
        <table>
          <thead>
            <tr>
              {columns.map((c) => <th key={c.key} scope="col">{c.label}</th>)}
            </tr>
          </thead>
          <tbody>
            {[0, 1, 2].map((i) => (
              <tr key={i}>
                {columns.map((c) => <td key={c.key}><span className="skeleton" /></td>)}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }

  if (rows.length === 0) {
    return <p role="status">No results match your filters.</p>;
  }

  const sortLabel = (c) => {
    if (c.key !== sortBy) return "none";
    return sortDir === "asc" ? "ascending" : "descending";
  };

  return (
    <table>
      <thead>
        <tr>
          {columns.map((c) => (
            <th key={c.key} scope="col" aria-sort={sortLabel(c)}>
              {c.sortable
                ? <button type="button" onClick={() => onSort(c.key)}>{c.label} {c.key === sortBy ? (sortDir === "asc" ? "\u25B2" : "\u25BC") : ""}</button>
                : c.label}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr
            key={row.id}
            onClick={() => onSelect(row.id)}
            onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onSelect(row.id); } }}
            tabIndex={0}
            aria-label={"View details for " + row.name}
            aria-selected={row.id === selectedId}
          >
            {columns.map((c) => <td key={c.key}>{row[c.key]}</td>)}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

