var COLUMNS = [
  { key: "name", label: "Name", sortable: true },
  { key: "role", label: "Role", sortable: true },
  { key: "level", label: "Level", sortable: true },
  { key: "location", label: "Location", sortable: true }
];

function DetailPanel(props) {
  var employee = props.employee;
  var onClose = props.onClose;
  var closeRef = React.useRef(null);

  React.useEffect(function () {
    var prevFocus = document.activeElement;
    if (closeRef.current) closeRef.current.focus();
    var onKey = function (e) {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", onKey);
    return function () {
      document.removeEventListener("keydown", onKey);
      if (prevFocus && prevFocus.focus) prevFocus.focus();
    };
  }, [onClose]);

  if (!employee) return null;

  return (
    <aside role="dialog" aria-modal="true" aria-labelledby="detail-title">
      <h2 id="detail-title">{employee.name}</h2>
      <dl>
        <dt>Role</dt><dd>{employee.role}</dd>
        <dt>Level</dt><dd>{employee.level}</dd>
        <dt>Location</dt><dd>{employee.location}</dd>
      </dl>
      <button ref={closeRef} type="button" onClick={onClose}>Close</button>
    </aside>
  );
}

function App() {
  var queryState = React.useState("");
  var query = queryState[0];
  var setQuery = queryState[1];
  var roleState = React.useState("all");
  var role = roleState[0];
  var setRole = roleState[1];
  var sortByState = React.useState("name");
  var sortBy = sortByState[0];
  var setSortBy = sortByState[1];
  var sortDirState = React.useState("asc");
  var sortDir = sortDirState[0];
  var setSortDir = sortDirState[1];
  var selState = React.useState(null);
  var selectedId = selState[0];
  var setSelectedId = selState[1];
  var empState = React.useState([]);
  var employees = empState[0];
  var setEmployees = empState[1];
  var loadState = React.useState(true);
  var loading = loadState[0];
  var setLoading = loadState[1];
  var errState = React.useState(null);
  var error = errState[0];
  var setError = errState[1];

  React.useEffect(function () {
    var cancelled = false;
    api.get("/employees").then(function (data) {
      if (!cancelled) {
        setEmployees(data.rows);
        setLoading(false);
      }
    }, function (err) {
      if (!cancelled) {
        setError(err && err.message ? err.message : "unknown error");
        setLoading(false);
      }
    });
    return function () { cancelled = true; };
  }, []);

  var visible = React.useMemo(function () {
    return applyFilters(employees, { query: query, role: role, sortBy: sortBy, sortDir: sortDir });
  }, [employees, query, role, sortBy, sortDir]);

  var selected = null;
  for (var i = 0; i < visible.length; i++) {
    if (visible[i].id === selectedId) selected = visible[i];
  }

  var handleSort = function (key) {
    if (key === sortBy) {
      setSortDir(sortDir === "asc" ? "desc" : "asc");
    } else {
      setSortBy(key);
      setSortDir("asc");
    }
  };

  if (error) return <p role="alert">Failed to load: {error}</p>;

  return (
    <main>
      <h1>Team directory</h1>
      <label>Search <input value={query} onChange={(e) => setQuery(e.target.value)} /></label>
      <label>Role <select value={role} onChange={(e) => setRole(e.target.value)}>
        <option value="all">All</option>
        <option value="engineer">Engineer</option>
        <option value="designer">Designer</option>
        <option value="manager">Manager</option>
      </select></label>
      <DataTable rows={visible} columns={COLUMNS} sortBy={sortBy} sortDir={sortDir} onSort={handleSort} loading={loading} selectedId={selectedId} onSelect={setSelectedId} />
      <DetailPanel employee={selected} onClose={() => setSelectedId(null)} />
    </main>
  );
}

